#' Irregular Box Plot from X-13ARIMA-SEATS seasonal adjustment run. 
#'
#' Generate boxplot of irregular component from a \code{seas} object generated by the \code{seasonal} package. 
#'
#' Version 1.7, 3/4/2025
#'
#' @param seas_obj \code{seas} object generated from a call of \code{seas} on a single time series
#'                 This is a required entry.
#' @param this_table Character string; X-13ARIMA-SEATS table name or abbreviation for an irregular. 
#'        Possible tables are \code{"irregular"}, \code{"irregularoutlieradj"}, \code{"modirregular"}, 
#'        \code{"d13"}, \code{"e3"}, \code{"s13"}, \code{"se3"}
#'        If not a valid table name, the function will print an error message and return a NULL.
#' @param main_title Character string; main title of plot. 
#'        A title will be generated if no title is specified.
#' @param sub_title Character string; subtitle of plot. There is no default subtitle.
#' @param this_y_label Character string; y-axis label for plot, if specified.
#' @param y_limit Numeric vector of length 2; Range of values for the y-axis. 
#'        Default is range of the series specified.
#' @param this_x_label Label for X axis. Default is \code{"Month"} or \code{"Quarter"}.
#' @param add_notch Logical scalar; indicates if notches will appear in the box plots  
#'        around the median. Default is no notches.
#' @param add_jitter Logical scalar; indicates if jittered dots are added to the boxplot.  
#'        Default is no jittered dots.
#' @param jitter_shape Integer scalar; code for point type used for jittered points.
#'        Default is \code{16}.
#' @param jitter_degree Numeric scalar; degree of jittering for points.
#'        Default is \code{0.2}
#' @param do_grid Logical scalar; indicates if certain plots will have grid lines. 
#'        Default is no grid lines. 
#' @param do_background Logical scalar; indicates grey background included in plot.
#'        Default is no grey background;
#' @param line_color Character string; color used for series in the plot.  
#'        Default is \code{'black'}. 
#' @return A \code{ggplot} object that generates a boxplot of user-specified irregular seris  
#'         from an X-13ARIMA-SEATS table. 
#'         If a suitable series not specified, print out error message and return NULL.
#'
#' @author Brian C. Monsell, \email{monsell.brian@@bls.gov} or \email{bcmonsell@@gmail.com}
#'
#' @examples
#' 
#' shoes_seas <-
#'     seasonal::seas(shoes2008, x11.save = "d13",
#'        x11 = "", transform.function = "log",
#'        check.print = c("none", "+acf", "+acfplot", "+normalitytest"),
#'        regression.aictest = c("td", "easter"),
#'		  regression.save = c("td", "hol"),
#'        outlier.types = "all",
#'        arima.model = "(0 1 1)(0 1 1)",
#'        forecast.maxlead = 60)
#'
#' p_bp1 <- 
#'    plot_irregular_boxplot(shoes_seas, "d13",
#'                           main_title = "X-11 Irregular by Month",
#'                           sub_title = "US Shoe Sales",
#'                           line_color = "steelblue")
#' 
#' p_bp1_notch <- 
#'    plot_irregular_boxplot(shoes_seas, "d13",
#'                           main_title = "X-11 Irregular by Month",
#'                           sub_title = "US Shoe Sales",
#'                           line_color = "steelblue",
#'                           add_notch = TRUE)
#' 
#' ukgas_seats_seas <- 
#'    seasonal::seas(UKgas, series.period = 4, arima.model = "(0 1 1)(0 1 1)", 
#'                   transform.function = "log", forecast.maxlead = 20,
#'                   check.print = c( 'pacf', 'pacfplot' ), seats.save = "se3")
#'
#' p_bp2 <- 
#'    plot_irregular_boxplot(ukgas_seats_seas, "se3",
#'                           main_title = "SEATS Outlier Adj Irregular by Quarter",
#'                           sub_title = "UK Gas Production",
#'                           line_color = "steelblue")
#' 
#' p_bp2_jitter <- 
#'    plot_irregular_boxplot(ukgas_seats_seas, "se3",
#'                           main_title = "SEATS Outlier Adj Irregular by Quarter",
#'                           sub_title = "UK Gas Production",
#'                           line_color = "steelblue",
#'                           add_jitter = TRUE,
#'                           jitter_degree = 0.25)
#' 
#' @importFrom rlang .data
#' @export
plot_irregular_boxplot <- 
    function(seas_obj = NULL, 
             this_table = NULL, 
             main_title = NULL, 
             sub_title = NULL, 
             this_y_label = NULL, 
             y_limit = NULL, 
             this_x_label = NULL,
			 add_notch = FALSE,
			 add_jitter = FALSE,
			 jitter_shape = 16,
			 jitter_degree = 0.2,
             do_grid = FALSE, 
             do_background = FALSE, 
             line_color = "black") {
    # Author: Brian C. Monsell (OEUS) Version 1.7, 3/4/2025
    
    # check if a value is specified for \code{seas_obj}
    if (is.null(seas_obj)) {
        cat("must specify a seas object")
		return(NULL)
    } else {
    # check if a seas object is specified for \code{seas_obj}
        if (!inherits(seas_obj, "seas")) {
            cat("First argument must be a seas object")
			return(NULL)
        }
    }
	
	if (is.null(this_table)) {
        cat("must specify a table name")
		return(NULL)
	} else {
		this_table <- tolower(this_table)
		all_irregular <- 
			c("irregular", "irregularoutlieradj", "modirregular", "d13", "e3", "s13", "se3")
		if (this_table %in% all_irregular) {
			this_irr <- seasonal::series(seas_obj, this_table)
		} else {
			cat("must specify one of the following table names:")
			cat(paste(all_irregular))
			return(NULL)
		}
		label_irregular <- 
			c("Irregular", "Outlier Adj Irregular", "Modified Irregular")
		index_irregular <- c(1, 2, 3, 1, 3, 1, 2)
		this_index_irr <- seq(1,7)[all_irregular %in% this_table]
	}
	
	# set frequency, x axis label
    freq <- frequency(this_irr)
	if (is.null(this_x_label)) {
		if (freq == 12) {
			this_x_label <- "Months"
		} else {
			this_x_label <- "Quarters"
		}
	}
	
	# set frequency label and period variable
	if (freq == 12) {
		this_freq_label <- "Month"
		this_period <-  factor(month.abb[cycle(this_irr)])
	} else {	
		this_freq_label <- "Quarter"
		this_period <-  factor(paste0("q", cycle(this_irr)))
	}
	
	# extract seasonal adjustment mode from UDG output
	this_mode <- as.character(substr(seasonal::udg(seas_obj, "samode"), 1, 5))
	if (!this_mode == "SEATS") {
		this_mode <- "X-11"
	}
	
	# generate title if not specified
	if (is.null(main_title)) {
		main_title <- paste(this_mode, label_irregular[this_index_irr], "by", this_freq_label) 
	}
	
	this_db <- data.frame(
		irr = as.double(this_irr),
		period = this_period
	)
	
	p_bp <- ggplot2::ggplot(this_db, ggplot2::aes(x=.data$period, y=.data$irr)) + 
			ggplot2::geom_boxplot(color = line_color, notch = add_notch) + 
            ggplot2::labs(title = main_title,
                          subtitle = sub_title,
                          y = this_y_label,
						  x = this_x_label)
						  
#   sort months in chronological order
	if (freq == 12) {
		p_bp <- p_bp + ggplot2::scale_x_discrete(limits=month.abb)
	}
	
	# remove grey background if \code{do_background = FALSE} 
    if (!do_background) {
		p_bp <- p_bp + ggplot2::theme_bw()
    }

	# remove grid lines if \code{do_grid = FALSE}
	if (!do_grid) {
	    p_bp <- p_bp + 
		    ggplot2::theme(panel.grid.major = ggplot2::element_blank(), 
		                   panel.grid.minor = ggplot2::element_blank())
	}
	
	if (add_jitter) {
		p_bp <- p_bp + 
			ggplot2::geom_jitter(shape=jitter_shape, 
				position=ggplot2::position_jitter(jitter_degree))
	}
	
	return(p_bp)
	
}